// case {{CASE_ID}}
const allowed = new Set(["name", "enabled"]);
const failure = error => ({ ok: false, error });
export function parseFields(text) {
  if (typeof text !== "string" || text.length === 0) return failure("empty");
  if (text.endsWith(";")) return failure("trailing_data");
  const value = {}; const seen = new Set();
  for (const part of text.split(";")) {
    const pieces = part.split("=");
    if (pieces.length !== 2 || pieces.some(piece => piece.length === 0)) return failure("invalid_delimiter");
    const [key, entry] = pieces;
    if (!allowed.has(key)) return failure("unknown_field");
    if (seen.has(key)) return failure("duplicate_field");
    seen.add(key); value[key] = entry;
  }
  return { ok: true, value };
}

