// case {{CASE_ID}}
function abortError() { return new DOMException("Aborted", "AbortError"); }
export function runTask(signal, scheduler, onComplete) {
  if (signal.aborted) return Promise.reject(abortError());
  return new Promise((resolve, reject) => {
    let settled = false; let cancel = null;
    const cleanup = () => signal.removeEventListener("abort", abort);
    const abort = () => { if (settled) return; settled = true; cancel?.(); cleanup(); reject(abortError()); };
    const finish = () => { if (settled) return; if (signal.aborted) { abort(); return; } settled = true; cleanup(); onComplete(); resolve("done"); };
    signal.addEventListener("abort", abort, { once: true });
    cancel = scheduler(finish);
  });
}

