export async function collectSources(first, second) {
  const settled = await Promise.allSettled([first(), second()]);
  const items = []; const errors = []; const names = ["first", "second"];
  settled.forEach((result, index) => {
    if (result.status === "rejected") errors.push({ source: names[index], code: "failed" });
