import path from "node:path";
const reserved = /^(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\..*)?$/i;
export function confinedPath(root, input) {
  if (typeof input !== "string" || input.length === 0 || path.isAbsolute(input) || /^[A-Za-z]:/.test(input) || input.includes("\\") || /%2f|%5c/i.test(input)) throw new Error("unsafe_path");
  const segments = input.split("/");
  if (segments.some(segment => segment === "" || segment === "." || segment === ".." || segment.endsWith(".") || reserved.test(segment))) throw new Error("unsafe_path");
  const resolved = path.resolve(root, ...segments); const relative = path.relative(path.resolve(root), resolved);
  if (relative.startsWith("..") || path.isAbsolute(relative)) throw new Error("unsafe_path");
  return resolved;
}

